mapper.select:
select t.id as id, t.tag_name as tag_name, t.class_id as class_id, tc.class_name as class_name, t.description as description, t.create_time as create_time, t.update_time as update_time, t.status as status from tag t left join tag_class tc on t.class_id = tc.id where t.status = 0
and t.tag_name like concat('%', #{tagName}, '%')
and t.class_id = #{classId}
